use vstd::prelude::*;

verus! {

pub struct Interval {
    pub min: int,
    pub max: int,
}

pub struct ChebyshevPoly {
    pub coef: Seq<i32>,
    pub domain: Interval,
    pub window: Interval,
}

impl Interval {
    pub open spec fn valid(&self) -> bool {
        self.min < self.max
    }
}

pub fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef@.len() > 0,
    ensures
        // (1) coefficients converted to i32, same length and order
        result.coef.len() == coef@.len(),
        forall|i: int|
            0 <= i < coef@.len() ==> result.coef[i] == coef@[i] as i32,

        // (2) default domain [-1, 1]
        result.domain.min == -1,
        result.domain.max ==  1,

        // (3) default window [-1, 1]
        result.window.min == -1,
        result.window.max ==  1,

        // validity constraints
        result.domain.valid(),
        result.window.valid(),
{
    let s: Seq<i32> = Seq::new(coef@.len(), |i: int| coef@[i] as i32);

    result = ChebyshevPoly {
        coef: s,
        domain: Interval { min: -1, max: 1 },
        window: Interval { min: -1, max: 1 },
    };
}

} // verus!